eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   HISTORY_SECTIONS: () => (/* binding */ HISTORY_SECTIONS)\n/* harmony export */ });\n/* __next_internal_client_entry_do_not_use__ HISTORY_SECTIONS auto */ const HISTORY_SECTIONS = [\n    {\n        id: \"cinematografo\",\n        year: \"1895\",\n        label: \"EL NACIMIENTO\",\n        title: \"El Cinemat\\xf3grafo de los Lumi\\xe8re\",\n        subtitle: \"La creaci\\xf3n del dispositivo que cambi\\xf3 la historia\",\n        image: \"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Institut_Lumi%C3%A8re_-_CINEMATOGRAPHE_Camera.jpg/250px-Institut_Lumi%C3%A8re_-_CINEMATOGRAPHE_Camera.jpg?utm_source=es.wikipedia.org&utm_campaign=parser&utm_content=thumbnail\",\n        alt: \"Cinemat\\xf3grafo de los hermanos Lumi\\xe8re\",\n        content: [\n            \"La idea de capturar, crear y reproducir el movimiento por medios mec\\xe1nicos es muy antigua, y existieron antecedentes como la c\\xe1mara oscura, el taumatropo, la linterna m\\xe1gica o el fusil fotogr\\xe1fico.\",\n            \"Inspir\\xe1ndose en estos y otros inventos como el rollo de fotos de Eastman, los hermanos Lumi\\xe8re crearon el cinemat\\xf3grafo: un dispositivo que permit\\xeda la toma, proyecci\\xf3n y copiado de im\\xe1genes en movimiento.\",\n            \"A diferencia del quinetoscopio de Edison (visualizaci\\xf3n individual), el cinemat\\xf3grafo permit\\xeda la proyecci\\xf3n colectiva, sentando las bases del cine como experiencia social.\"\n        ],\n        sideNote: \"El cinemat\\xf3grafo pesaba solo 5 kg y serv\\xeda como c\\xe1mara, proyector y copiadora.\"\n    },\n    {\n        id: \"primera-proyeccion\",\n        year: \"1895\",\n        label: \"LA PRIMERA VEZ\",\n        title: \"Primera Proyecci\\xf3n P\\xfablica\",\n        subtitle: \"Sal\\xf3n Indio del Gran Caf\\xe9, Par\\xeds — 28 diciembre 1895\",\n        image: \" https://newpostcity.wordpress.com/wp-content/uploads/2016/03/salon-indien-grand-cafe2.jpg \",\n        alt: \"Llegada del tren a La Ciotat - primer filme proyectado\",\n        content: [\n            \"El 28 de diciembre de 1895 se realiza la primera proyecci\\xf3n abierta al p\\xfablico en el Sal\\xf3n Indio del Gran Caf\\xe9 de Par\\xeds. Por solo un franco, cualquier persona interesada pudo asistir a este evento hist\\xf3rico.\",\n            'Se proyectaron 10 pel\\xedculas de aproximadamente 50 segundos cada una, incluyendo \"La salida de la f\\xe1brica Lumi\\xe8re en Lyon\" y \"La llegada del tren a La Ciotat\".',\n            \"La leyenda cuenta que el p\\xfablico huy\\xf3 despavorido al ver el tren acercarse en pantalla, aunque los historiadores debaten la veracidad de este mito fundacional.\"\n        ],\n        sideNote: 'Los Lumi\\xe8re consideraban el cine \"un invento sin futuro comercial\".'\n    },\n    {\n        id: \"melies\",\n        year: \"1902\",\n        label: \"LA FICCI\\xd3N\",\n        title: \"Georges M\\xe9li\\xe8s y el Cine de Ficci\\xf3n\",\n        subtitle: \"Viaje a la Luna — La primera pel\\xedcula de ciencia ficci\\xf3n\",\n        image: \"https://encadenados.org/wp-content/uploads/2016/01/rashomon_num_91_viaje-a-la-luna-0.jpg\",\n        alt: \"Viaje a la Luna - Georges M\\xe9li\\xe8s\",\n        content: [\n            'Georges M\\xe9li\\xe8s, ilusionista y cineasta franc\\xe9s, llev\\xf3 el cine m\\xe1s all\\xe1 de la documentaci\\xf3n de la realidad. En 1902 estren\\xf3 \"Viaje a la Luna\", considerada la primera pel\\xedcula de ciencia ficci\\xf3n y la primera en usar efectos especiales narrativos.',\n            \"M\\xe9li\\xe8s invent\\xf3 t\\xe9cnicas como la sustituci\\xf3n (stop trick), la exposici\\xf3n m\\xfaltiple, la disoluci\\xf3n encadenada y el uso de maquetas pintadas, sentando las bases del lenguaje cinematogr\\xe1fico narrativo.\",\n            'Su estudio en Montreuil fue el primer \"estudio de cine\" de la historia, donde controlaba totalmente la iluminaci\\xf3n y el decorado — precursor del sistema de estudios de Hollywood.'\n        ],\n        sideNote: \"M\\xe9li\\xe8s dirigi\\xf3 m\\xe1s de 500 pel\\xedculas; la mayor\\xeda se perdieron al fundir el celuloide para hacer botones de uniforme en la WWI.\"\n    },\n    {\n        id: \"sonido\",\n        year: \"1927\",\n        label: \"EL SONIDO\",\n        title: \"El Cine Habla\",\n        subtitle: \"The Jazz Singer y el nacimiento del cine sonoro\",\n        image: \" https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSV4A5M4XUZKGj5z4Wrtlo7AZHgo7KU8NqRGthQmBXuDGpJ9zaIbSC0ZfiU&s=10 \",\n        alt: \"The Jazz Singer de 1927\",\n        content: [\n            \"La llegada del sonido sincronizado transform\\xf3 radicalmente la experiencia cinematogr\\xe1fica. Las pel\\xedculas dejaron de depender exclusivamente de la imagen y comenzaron a incorporar di\\xe1logos, m\\xfasica y efectos sonoros sincronizados.\",\n            \"The Jazz Singer, estrenada en 1927, marc\\xf3 un punto de inflexi\\xf3n comercial en la transici\\xf3n hacia el cine sonoro.\",\n            \"La nueva tecnolog\\xeda oblig\\xf3 a los estudios, actores y directores a modificar sus m\\xe9todos de trabajo y cambi\\xf3 para siempre el lenguaje cinematogr\\xe1fico.\"\n        ],\n        sideNote: \"La transici\\xf3n al sonido hizo que muchas estrellas del cine mudo perdieran popularidad debido a sus voces o dificultades para adaptarse.\"\n    },\n    {\n        id: \"color\",\n        year: \"1939\",\n        label: \"EL COLOR\",\n        title: \"El Cine se Llena de Color\",\n        subtitle: \"Technicolor y la transformaci\\xf3n visual de Hollywood\",\n        image: \"https://m.media-amazon.com/images/M/MV5BYmYxZTE3YzMtYmE2Yy00NmFlLTkzYTAtYTAzN2IzNDFkN2E0XkEyXkFqcGc@._V1_.jpg\",\n        alt: \"Gone with the Wind y el cine en Technicolor\",\n        content: [\n            \"El desarrollo de sistemas de color cada vez m\\xe1s sofisticados permiti\\xf3 que las pel\\xedculas adquirieran una nueva dimensi\\xf3n visual.\",\n            \"Technicolor se convirti\\xf3 en uno de los sistemas m\\xe1s importantes de la \\xe9poca y fue utilizado en grandes producciones de Hollywood.\",\n            \"Gone with the Wind, estrenada en 1939, se convirti\\xf3 en uno de los ejemplos m\\xe1s conocidos del impacto espectacular que pod\\xeda producir el color en una gran producci\\xf3n cinematogr\\xe1fica.\"\n        ],\n        sideNote: \"El color no reemplaz\\xf3 inmediatamente al blanco y negro: durante d\\xe9cadas ambos sistemas coexistieron.\"\n    },\n    {\n        id: \"nuevas-formas\",\n        year: \"1950\",\n        label: \"NUEVAS FORMAS\",\n        title: \"La Pantalla se Transforma\",\n        subtitle: \"Televisi\\xf3n, nuevos formatos y nuevas experiencias\",\n        image: \"https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSaR9lzaKoXwpA2trIZeRtm1csJcKm7ZxQpV38LcasOhTxIauoQXAjMoSQx&s=10\",\n        alt: \"Vertigo y la transformaci\\xf3n del cine cl\\xe1sico\",\n        content: [\n            \"La expansi\\xf3n de la televisi\\xf3n oblig\\xf3 al cine a buscar nuevas formas de atraer al p\\xfablico hacia las salas.\",\n            \"Las producciones comenzaron a experimentar con formatos panor\\xe1micos, nuevas tecnolog\\xedas de sonido y experiencias visuales cada vez m\\xe1s espectaculares.\",\n            \"Durante este periodo surgieron algunas de las obras m\\xe1s influyentes del cine moderno, mientras Hollywood buscaba diferenciar la experiencia cinematogr\\xe1fica de la televisi\\xf3n dom\\xe9stica.\"\n        ],\n        sideNote: \"La aparici\\xf3n de la televisi\\xf3n fue uno de los grandes desaf\\xedos comerciales que enfrent\\xf3 la industria cinematogr\\xe1fica.\"\n    },\n    {\n        id: \"blockbuster\",\n        year: \"1977\",\n        label: \"BLOCKBUSTER\",\n        title: \"El Nacimiento del Cine Espect\\xe1culo\",\n        subtitle: \"Star Wars y una nueva era para Hollywood\",\n        image: \"https://upload.wikimedia.org/wikipedia/en/8/87/StarWarsMoviePoster1977.jpg\",\n        alt: \"P\\xf3ster de Star Wars de 1977\",\n        content: [\n            \"En 1977, Star Wars transform\\xf3 la manera en que Hollywood conceb\\xeda las grandes producciones comerciales.\",\n            \"George Lucas combin\\xf3 efectos especiales, aventura, ciencia ficci\\xf3n y una estrategia de lanzamiento que convirti\\xf3 la pel\\xedcula en un fen\\xf3meno cultural.\",\n            \"El \\xe9xito de estas grandes producciones consolid\\xf3 el modelo de blockbuster y cambi\\xf3 la relaci\\xf3n entre cine, merchandising, publicidad y cultura popular.\"\n        ],\n        sideNote: \"Star Wars ayud\\xf3 a establecer una nueva forma de entender una pel\\xedcula como una experiencia cultural que pod\\xeda extenderse mucho m\\xe1s all\\xe1 de la sala.\"\n    },\n    {\n        id: \"digital\",\n        year: \"1995\",\n        label: \"ERA DIGITAL\",\n        title: \"El Cine Entra en la Era Digital\",\n        subtitle: \"Toy Story y la revoluci\\xf3n de la animaci\\xf3n por ordenador\",\n        image: \"https://upload.wikimedia.org/wikipedia/en/1/13/Toy_Story.jpg\",\n        alt: \"P\\xf3ster de Toy Story\",\n        content: [\n            \"La llegada de las herramientas digitales comenz\\xf3 a transformar profundamente la producci\\xf3n cinematogr\\xe1fica.\",\n            \"En 1995, Toy Story se convirti\\xf3 en un momento hist\\xf3rico para la animaci\\xf3n al ser el primer largometraje completamente realizado mediante im\\xe1genes generadas por ordenador.\",\n            \"La tecnolog\\xeda digital abri\\xf3 nuevas posibilidades creativas y cambi\\xf3 progresivamente la forma de producir, editar, distribuir y experimentar el cine.\"\n        ],\n        sideNote: \"La revoluci\\xf3n digital no ocurri\\xf3 de un d\\xeda para otro: durante a\\xf1os convivieron procesos tradicionales y digitales.\"\n    },\n    {\n        id: \"streaming\",\n        year: \"2020\",\n        label: \"STREAMING\",\n        title: \"El Cine Cambia de Pantalla\",\n        subtitle: \"La expansi\\xf3n definitiva de las plataformas digitales\",\n        image: \" https://www.socialfuturo.com/wp-content/uploads/2023/11/netflix-vs-cine-aburrimiento-vs-diversion.jpg \",\n        alt: \"Sala de cine y experiencia audiovisual\",\n        content: [\n            \"La expansi\\xf3n del streaming transform\\xf3 profundamente la manera en que el p\\xfablico accede a pel\\xedculas y series.\",\n            \"Durante la pandemia de 2020, el cierre de las salas cinematogr\\xe1ficas aceler\\xf3 todav\\xeda m\\xe1s la adopci\\xf3n de plataformas digitales y nuevas formas de distribuci\\xf3n.\",\n            \"El cine contin\\xfaa evolucionando entre las salas tradicionales, las plataformas digitales y nuevas experiencias audiovisuales.\"\n        ],\n        sideNote: \"La historia del cine contin\\xfaa escribi\\xe9ndose con cada nueva tecnolog\\xeda y cada nueva forma de contar historias.\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./app/history/page.tsx\n");

